template <class T>
struct RESTObjectCodec : public RESTCodec<RESTObjectCodec<T>> {
	template <class U>
	static U Get(RESTJsonIn in) {
		return DuckLakeRESTSerializer::Read<U>(in);
	}
	static JSONMutableValue Write(JSONWriter &writer, const T &value) {
		return DuckLakeRESTSerializer::Write(writer, value);
	}
	static void Read(RESTJsonIn in, T &result) {
		result = DuckLakeRESTSerializer::Read<T>(in);
	}
};

//! The requests of a commit, by the endpoint they can also be sent to on their own
struct RESTCommitRequestCodec : public RESTCodec<RESTCommitRequestCodec> {
	static JSONMutableValue Write(JSONWriter &writer, const RESTCommitRequest &value);
	static void Read(RESTJsonIn in, unique_ptr<RESTCommitRequest> &result);
};

inline bool RESTIsNull(const DuckLakeFileData &value) {
	return value.path.empty();
}
inline bool RESTIsNull(const DuckLakeSnapshot &value) {
	return value.snapshot_id == DConstants::INVALID_INDEX;
}

//! The types of rows that are given by a field of a list of objects
template <class T, class MEMBER>
vector<LogicalType> RESTRowTypes(const vector<T> &entries, MEMBER member) {
	vector<LogicalType> result;
	for (auto &entry : entries) {
		result.push_back(entry.*member);
	}
	return result;
}

//===--------------------------------------------------------------------===//
// Commit requests
//===--------------------------------------------------------------------===//
enum class RESTCommitRequestType : uint8_t {
	ALTER_TABLE,
	ALTER_VIEW,
	COMPACT,
	CREATE_MACRO,
	CREATE_NAME_MAP,
	CREATE_SCHEMA,
	CREATE_TABLE,
	CREATE_VIEW,
	DELETE_DATA,
	DROP_MACRO,
	DROP_SCHEMA,
	DROP_TABLE,
	DROP_VIEW,
	FLUSH_INLINED_DATA,
	INSERT_FILES,
	INSERT_ROWS,
	SET_OPTION,
};

//! A request of a commit_transaction
struct RESTCommitRequest {
	explicit RESTCommitRequest(RESTCommitRequestType type) : type(type) {
	}
	virtual ~RESTCommitRequest() {
	}

	RESTCommitRequestType type;

	//! The endpoint of the request
	const char *Path() const;
	static optional_idx TypeFromPath(const string &path);

	template <class TARGET>
	TARGET &Cast() {
		D_ASSERT(type == TARGET::TYPE);
		return static_cast<TARGET &>(*this);
	}
	template <class TARGET>
	const TARGET &Cast() const {
		D_ASSERT(type == TARGET::TYPE);
		return static_cast<const TARGET &>(*this);
	}
};

//===--------------------------------------------------------------------===//
// Unions
//===--------------------------------------------------------------------===//
enum class RESTAlterationType : uint8_t {
	RENAME_TABLE,
	RENAME_VIEW,
	RENAME_COLUMN,
	RENAME_FIELD,
	ADD_COLUMN,
	ADD_FIELD,
	REMOVE_COLUMN,
	REMOVE_FIELD,
	CHANGE_COLUMN_TYPE,
	SET_DEFAULT,
	SET_NOT_NULL,
	DROP_NOT_NULL,
	SET_PARTITIONED_BY,
	SET_SORTED_BY,
	SET_OPTIONS,
	RESET_OPTIONS,
	SET_COMMENT,
	SET_COLUMN_COMMENT,
};

//! The change of an `alter_table` or `alter_view` request: an object with exactly one member, the name of the change.
struct RESTAlteration {
	explicit RESTAlteration(RESTAlterationType type) : type(type) {
	}
	virtual ~RESTAlteration() {
	}

	RESTAlterationType type;

	template <class TARGET>
	TARGET &Cast() {
		D_ASSERT(type == TARGET::TYPE);
		return static_cast<TARGET &>(*this);
	}
	template <class TARGET>
	const TARGET &Cast() const {
		D_ASSERT(type == TARGET::TYPE);
		return static_cast<const TARGET &>(*this);
	}
};

struct RESTAlterationCodec : public RESTCodec<RESTAlterationCodec> {
	static JSONMutableValue Write(JSONWriter &writer, const RESTAlteration &value);
	static void Read(RESTJsonIn in, unique_ptr<RESTAlteration> &result);
	static void ReadPtr(RESTJsonIn in, unique_ptr<RESTAlteration> &result) {
		Read(in, result);
	}
};

