//===--------------------------------------------------------------------===//
// Server
//===--------------------------------------------------------------------===//
//! The handlers of the endpoints of the server, see ducklake_rest_endpoints.cpp
struct DuckLakeRESTEndpoints {
	//! Returns the name maps of files that were added with `ducklake_add_data_files`, starting from a mapping id.
	static RESTColumnMappingsResponse ColumnMappings(DuckLakeRESTRequest &request,
	                                                 const RESTColumnMappingsRequest &parameters);
	//! Returns the global metadata of the DuckLake (the contents of `ducklake_metadata`).
	static DuckLakeMetadata Config(DuckLakeRESTRequest &request, const RESTConfigRequest &parameters);
	//! Returns the deleted versions of the inlined rows of a table that a flush writes.
	static RESTDeletedInlinedRowsResponse DeletedInlinedRows(DuckLakeRESTRequest &request,
	                                                         const RESTDeletedInlinedRowsRequest &parameters);
	//! Returns the contents of a table of the DuckLake specification, as it is stored in the catalog.
	static RESTInlinedRows DuckLakeTable(DuckLakeRESTRequest &request, const RESTDuckLakeTableRequest &parameters);
	//! Returns the names of the tables of the DuckLake specification (`ducklake_snapshot`, `ducklake_data_file`, ...).
	static RESTDuckLakeTablesResponse DuckLakeTables(DuckLakeRESTRequest &request,
	                                                 const RESTDuckLakeTablesRequest &parameters);
	//! Returns the data files of a table that are candidates for compaction, together with their delete files.
	static RESTFilesForCompactionResponse FilesForCompaction(DuckLakeRESTRequest &request,
	                                                         const RESTFilesForCompactionRequest &parameters);
	//! Reads the inlined rows of a table that a flush writes.
	static RESTInlinedRows InlinedDataForFlush(DuckLakeRESTRequest &request,
	                                           const RESTInlinedDataForFlushRequest &parameters);
	//! Returns the deletions of rows of data files that are inlined in the catalog.
	static RESTInlinedFileDeletionsResponse InlinedFileDeletions(DuckLakeRESTRequest &request,
	                                                             const RESTInlinedFileDeletionsRequest &parameters);
	//! Returns the schema versions that a table has inlined rows for.
	static RESTInlinedTablesResponse InlinedTables(DuckLakeRESTRequest &request,
	                                               const RESTInlinedTablesRequest &parameters);
	//! Returns the snapshots, optionally filtered.
	static RESTListSnapshotsResponse ListSnapshots(DuckLakeRESTRequest &request,
	                                               const RESTListSnapshotsRequest &parameters);
	//! Returns the next free column (field) id of a table.
	static RESTNextColumnIdResponse NextColumnId(DuckLakeRESTRequest &request,
	                                             const RESTNextColumnIdRequest &parameters);
	//! Counts the rows of a table that are visible in a snapshot.
	static RESTRowCountResponse RowCount(DuckLakeRESTRequest &request, const RESTRowCountRequest &parameters);
	//! Plans a scan of a table.
	static RESTSelectResponse Select(DuckLakeRESTRequest &request, const RESTSelectRequest &parameters);
	//! Returns a snapshot together with (optionally) the catalog and the table statistics of that snapshot.
	static RESTSnapshotDataResponse SnapshotData(DuckLakeRESTRequest &request,
	                                             const RESTSnapshotDataRequest &parameters);
	//! Returns the files that hold the changes of a table between two snapshots, for change data feeds.
	static RESTTableChangesResponse TableChanges(DuckLakeRESTRequest &request,
	                                             const RESTTableChangesRequest &parameters);
	//! Returns when a table and its schema versions were created.
	static RESTTableSchemaVersionsResponse TableSchemaVersions(DuckLakeRESTRequest &request,
	                                                           const RESTTableSchemaVersionsRequest &parameters);
	//! Returns the storage used by each table at a snapshot.
	static RESTTableSizesResponse TableSizes(DuckLakeRESTRequest &request, const RESTTableSizesRequest &parameters);
	//! Returns the tables that have data files that are not deleted.
	static RESTTablesWithLiveDataFilesResponse
	TablesWithLiveDataFiles(DuckLakeRESTRequest &request, const RESTTablesWithLiveDataFilesRequest &parameters);
	//! Expires snapshots.
	static RESTExpireSnapshotsResponse ExpireSnapshots(DuckLakeRESTRequest &request,
	                                                   const RESTExpireSnapshotsRequest &parameters);
	//! Returns the files scheduled for deletion.
	static RESTFilesForCleanupResponse FilesForCleanup(DuckLakeRESTRequest &request,
	                                                   const RESTFilesForCleanupRequest &parameters);
	//! Returns the paths of all files that the catalog refers to.
	static RESTKnownFilesResponse KnownFiles(DuckLakeRESTRequest &request, const RESTKnownFilesRequest &parameters);
	//! Removes files from the files scheduled for deletion, after the client deleted them.
	static void RemoveCleanedUpFiles(DuckLakeRESTRequest &request, const RESTRemoveCleanedUpFilesRequest &parameters);
	//! Commits a set of changes atomically.
	static RESTCommitTransactionResponse CommitTransaction(DuckLakeRESTRequest &request,
	                                                       const RESTCommitTransactionRequest &parameters);
};

//! Applies the requests of a commit
class DuckLakeRESTCommitHandler {
public:
	virtual ~DuckLakeRESTCommitHandler() {
	}

	//! The handlers can take over the parameters of the requests
	void Apply(RESTCommitRequest &request);

protected:
	virtual void AlterTable(RESTAlterTableRequest &request) = 0;
	virtual void AlterView(RESTAlterViewRequest &request) = 0;
	virtual void Compact(RESTCompactRequest &request) = 0;
	virtual void CreateMacro(RESTCreateMacroRequest &request) = 0;
	virtual void CreateNameMap(RESTCreateNameMapRequest &request) = 0;
	virtual void CreateSchema(RESTCreateSchemaRequest &request) = 0;
	virtual void CreateTable(RESTCreateTableRequest &request) = 0;
	virtual void CreateView(RESTCreateViewRequest &request) = 0;
	virtual void DeleteData(RESTDeleteDataRequest &request) = 0;
	virtual void DropMacro(RESTDropMacroRequest &request) = 0;
	virtual void DropSchema(RESTDropSchemaRequest &request) = 0;
	virtual void DropTable(RESTDropTableRequest &request) = 0;
	virtual void DropView(RESTDropViewRequest &request) = 0;
	virtual void FlushInlinedData(RESTFlushInlinedDataRequest &request) = 0;
	virtual void InsertFiles(RESTInsertFilesRequest &request) = 0;
	virtual void InsertRows(RESTInsertRowsRequest &request) = 0;
	virtual void SetOption(RESTSetOptionRequest &request) = 0;
};

//! Handles the JSON body of a request to an endpoint, returns the JSON body of the response
typedef string (*rest_endpoint_t)(DuckLakeRESTRequest &request, const string &body);

struct DuckLakeRESTAPI {
	//! The endpoints of the API, by their name
	static const unordered_map<string, rest_endpoint_t> &GetEndpoints();
};

//===--------------------------------------------------------------------===//
// Client
//===--------------------------------------------------------------------===//
//! The endpoints of the API, as called by a client
class DuckLakeRESTClientAPI {
public:
	virtual ~DuckLakeRESTClientAPI() {
	}

	//! Returns the name maps of files that were added with `ducklake_add_data_files`, starting from a mapping id.
	RESTColumnMappingsResponse ColumnMappings(const RESTColumnMappingsRequest &request);
	//! Returns the global metadata of the DuckLake (the contents of `ducklake_metadata`).
	DuckLakeMetadata Config(const RESTConfigRequest &request);
	//! Returns the deleted versions of the inlined rows of a table that a flush writes.
	RESTDeletedInlinedRowsResponse DeletedInlinedRows(const RESTDeletedInlinedRowsRequest &request);
	//! Returns the contents of a table of the DuckLake specification, as it is stored in the catalog.
	RESTInlinedRows DuckLakeTable(const RESTDuckLakeTableRequest &request);
	//! Returns the names of the tables of the DuckLake specification (`ducklake_snapshot`, `ducklake_data_file`, ...).
	RESTDuckLakeTablesResponse DuckLakeTables(const RESTDuckLakeTablesRequest &request);
	//! Returns the data files of a table that are candidates for compaction, together with their delete files.
	RESTFilesForCompactionResponse FilesForCompaction(const RESTFilesForCompactionRequest &request);
	//! Reads the inlined rows of a table that a flush writes.
	RESTInlinedRows InlinedDataForFlush(const RESTInlinedDataForFlushRequest &request);
	//! Returns the deletions of rows of data files that are inlined in the catalog.
	RESTInlinedFileDeletionsResponse InlinedFileDeletions(const RESTInlinedFileDeletionsRequest &request);
	//! Returns the schema versions that a table has inlined rows for.
	RESTInlinedTablesResponse InlinedTables(const RESTInlinedTablesRequest &request);
	//! Returns the snapshots, optionally filtered.
	RESTListSnapshotsResponse ListSnapshots(const RESTListSnapshotsRequest &request);
	//! Returns the next free column (field) id of a table.
	RESTNextColumnIdResponse NextColumnId(const RESTNextColumnIdRequest &request);
	//! Counts the rows of a table that are visible in a snapshot.
	RESTRowCountResponse RowCount(const RESTRowCountRequest &request);
	//! Plans a scan of a table.
	RESTSelectResponse Select(const RESTSelectRequest &request);
	//! Returns a snapshot together with (optionally) the catalog and the table statistics of that snapshot.
	RESTSnapshotDataResponse SnapshotData(const RESTSnapshotDataRequest &request);
	//! Returns the files that hold the changes of a table between two snapshots, for change data feeds.
	RESTTableChangesResponse TableChanges(const RESTTableChangesRequest &request);
	//! Returns when a table and its schema versions were created.
	RESTTableSchemaVersionsResponse TableSchemaVersions(const RESTTableSchemaVersionsRequest &request);
	//! Returns the storage used by each table at a snapshot.
	RESTTableSizesResponse TableSizes(const RESTTableSizesRequest &request);
	//! Returns the tables that have data files that are not deleted.
	RESTTablesWithLiveDataFilesResponse TablesWithLiveDataFiles(const RESTTablesWithLiveDataFilesRequest &request);
	//! Expires snapshots.
	RESTExpireSnapshotsResponse ExpireSnapshots(const RESTExpireSnapshotsRequest &request);
	//! Returns the files scheduled for deletion.
	RESTFilesForCleanupResponse FilesForCleanup(const RESTFilesForCleanupRequest &request);
	//! Returns the paths of all files that the catalog refers to.
	RESTKnownFilesResponse KnownFiles(const RESTKnownFilesRequest &request);
	//! Removes files from the files scheduled for deletion, after the client deleted them.
	void RemoveCleanedUpFiles(const RESTRemoveCleanedUpFilesRequest &request);
	//! Alters a table.
	RESTCommitTransactionResponse AlterTable(const RESTAlterTableRequest &request);
	//! Alters a view.
	RESTCommitTransactionResponse AlterView(const RESTAlterViewRequest &request);
	//! Commits a set of changes atomically.
	RESTCommitTransactionResponse CommitTransaction(const RESTCommitTransactionRequest &request);
	//! Replaces data files with compacted files that were written by the client.
	RESTCommitTransactionResponse Compact(const RESTCompactRequest &request);
	//! Creates a macro.
	RESTCommitTransactionResponse CreateMacro(const RESTCreateMacroRequest &request);
	//! Registers a name map for files that are inserted later in the transaction.
	RESTCommitTransactionResponse CreateNameMap(const RESTCreateNameMapRequest &request);
	//! Creates a schema.
	RESTCommitTransactionResponse CreateSchema(const RESTCreateSchemaRequest &request);
	//! Creates a table.
	RESTCommitTransactionResponse CreateTable(const RESTCreateTableRequest &request);
	//! Creates a view.
	RESTCommitTransactionResponse CreateView(const RESTCreateViewRequest &request);
	//! Deletes rows from a table.
	RESTCommitTransactionResponse DeleteData(const RESTDeleteDataRequest &request);
	//! Drops a macro.
	RESTCommitTransactionResponse DropMacro(const RESTDropMacroRequest &request);
	//! Drops a schema, which has to be empty.
	RESTCommitTransactionResponse DropSchema(const RESTDropSchemaRequest &request);
	//! Drops a table.
	RESTCommitTransactionResponse DropTable(const RESTDropTableRequest &request);
	//! Drops a view.
	RESTCommitTransactionResponse DropView(const RESTDropViewRequest &request);
	//! Marks inlined data as flushed.
	RESTCommitTransactionResponse FlushInlinedData(const RESTFlushInlinedDataRequest &request);
	//! Registers Parquet files that were written by the client.
	RESTCommitTransactionResponse InsertFiles(const RESTInsertFilesRequest &request);
	//! Inserts rows that are inlined in the catalog.
	RESTCommitTransactionResponse InsertRows(const RESTInsertRowsRequest &request);
	//! Sets or resets a DuckLake option (`ducklake_metadata`).
	RESTCommitTransactionResponse SetOption(const RESTSetOptionRequest &request);

	//! Maps the paths of the requests and responses to and from the data path of the server, if set
	virtual optional_ptr<const RESTPathMapper> GetPathMapper() const {
		return nullptr;
	}

	//! Sends the JSON body of a request to an endpoint, returns the JSON body of the response
	//! Rethrows the error reported by the server
	//! Requests of idempotent endpoints can be sent again, e.g. if the connection was closed by the server
	virtual string Post(const string &endpoint, const string &body, bool idempotent) = 0;
};

